{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://json.schemastore.org/claude-code-settings.json",
  "$defs": {
    "permissionRule": {
      "type": "string",
      "description": "Tool permission rule. See https://code.claude.com/docs/en/settings#permission-rule-syntax",
      "pattern": "^((Bash|Edit|ExitPlanMode|Glob|Grep|KillShell|LS|MultiEdit|NotebookEdit|NotebookRead|Read|Skill|SlashCommand|Task|TodoWrite|WebFetch|WebSearch|Write)(\\((?=.*[^)*?])[^)]+\\))?|mcp__.*)$",
      "examples": [
        "Bash",
        "Bash(npm run build)",
        "Bash(git commit:*)",
        "Bash(npm run:*)",
        "Bash(ls*)",
        "Bash(git * main)",
        "Edit",
        "MultiEdit",
        "Edit(/src/**/*.ts)",
        "Read(./.env)",
        "Read(./secrets/**)",
        "Read(/Users/alice/secrets/**)",
        "Read(~/Documents/*.pdf)",
        "SlashCommand(/clear)",
        "WebFetch",
        "WebFetch(domain:example.com)",
        "mcp__github__search_repositories"
      ]
    },
    "hookCommand": {
      "anyOf": [
        {
          "type": "object",
          "description": "Bash command hook",
          "additionalProperties": false,
          "required": ["type", "command"],
          "properties": {
            "type": {
              "type": "string",
              "description": "Hook type",
              "const": "command"
            },
            "command": {
              "type": "string",
              "description": "Shell command to execute",
              "minLength": 1
            },
            "timeout": {
              "type": "number",
              "description": "Optional timeout in seconds",
              "exclusiveMinimum": 0
            },
            "async": {
              "type": "boolean",
              "description": "Run this hook asynchronously without blocking Claude Code"
            }
          }
        },
        {
          "type": "object",
          "description": "LLM prompt hook",
          "additionalProperties": false,
          "required": ["type", "prompt"],
          "properties": {
            "type": {
              "type": "string",
              "description": "Hook type",
              "const": "prompt"
            },
            "prompt": {
              "type": "string",
              "description": "Prompt to evaluate with LLM. Use $ARGUMENTS placeholder for hook input JSON.",
              "minLength": 1
            },
            "timeout": {
              "type": "number",
              "description": "Optional timeout in seconds",
              "exclusiveMinimum": 0
            },
            "async": {
              "type": "boolean",
              "description": "Run this hook asynchronously without blocking Claude Code"
            }
          }
        }
      ]
    },
    "hookMatcher": {
      "type": "object",
      "description": "Hook matcher configuration with multiple hooks",
      "additionalProperties": false,
      "required": ["hooks"],
      "properties": {
        "matcher": {
          "type": "string",
          "description": "Optional pattern to match tool names, case-sensitive (only applicable for PreToolUse and PostToolUse)"
        },
        "hooks": {
          "type": "array",
          "description": "Array of hooks to execute",
          "items": {
            "$ref": "#/$defs/hookCommand"
          }
        }
      }
    }
  },
  "description": "Configuration settings for Claude Code. Learn more: https://code.claude.com/docs/en/settings",
  "allowTrailingCommas": true,
  "additionalProperties": true,
  "type": "object",
  "properties": {
    "$schema": {
      "type": "string",
      "description": "JSON Schema reference for Claude Code settings"
    },
    "apiKeyHelper": {
      "type": "string",
      "description": "Path to a script that outputs authentication values",
      "examples": ["/bin/generate_temp_api_key.sh"],
      "minLength": 1
    },
    "autoUpdatesChannel": {
      "type": "string",
      "enum": ["stable", "latest"],
      "description": "Release channel to follow for updates. Use \"stable\" for a version that is typically about one week old and skips versions with major regressions, or \"latest\" (default) for the most recent release",
      "default": "latest"
    },
    "awsCredentialExport": {
      "type": "string",
      "description": "Path to a script that exports AWS credentials",
      "examples": ["/bin/generate_aws_grant.sh"],
      "minLength": 1
    },
    "awsAuthRefresh": {
      "type": "string",
      "description": "Path to a script that refreshes AWS authentication",
      "examples": ["aws sso login --profile myprofile"],
      "minLength": 1
    },
    "cleanupPeriodDays": {
      "type": "integer",
      "minimum": 0,
      "description": "Number of days to retain chat transcripts (0 to disable cleanup)",
      "examples": [20, 30, 60],
      "default": 30
    },
    "env": {
      "type": "object",
      "additionalProperties": false,
      "description": "Environment variables to set for Claude Code sessions",
      "examples": [
        {
          "ANTHROPIC_MODEL": "claude-opus-4-1",
          "ANTHROPIC_SMALL_FAST_MODEL": "claude-3-5-haiku-latest"
        }
      ],
      "default": {},
      "patternProperties": {
        "^[A-Z_][A-Z0-9_]*$": {
          "type": "string",
          "description": "Environment variable value"
        }
      }
    },
    "attribution": {
      "type": "object",
      "description": "Customize attribution for git commits and pull requests. See https://code.claude.com/docs/en/settings#attribution-settings",
      "additionalProperties": false,
      "properties": {
        "commit": {
          "type": "string",
          "description": "Attribution for git commits, including any trailers. Empty string hides commit attribution"
        },
        "pr": {
          "type": "string",
          "description": "Attribution for pull request descriptions. Empty string hides pull request attribution"
        }
      }
    },
    "includeCoAuthoredBy": {
      "type": "boolean",
      "description": "DEPRECATED. Use 'attribution' instead. Whether to include the co-authored-by Claude byline in git commits and pull requests (default: true)",
      "default": true
    },
    "plansDirectory": {
      "type": "string",
      "description": "Customize where plan files are stored. Path is relative to project root (default: ~/.claude/plans)",
      "default": "~/.claude/plans",
      "examples": ["./plans"]
    },
    "respectGitignore": {
      "type": "boolean",
      "description": "Control whether the @ file picker respects .gitignore patterns. When true (default), files matching .gitignore patterns are excluded from suggestions",
      "default": true
    },
    "permissions": {
      "type": "object",
      "properties": {
        "allow": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/permissionRule"
          },
          "description": "List of permission rules for allowed operations",
          "uniqueItems": true
        },
        "deny": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/permissionRule"
          },
          "description": "List of permission rules for denied operations",
          "uniqueItems": true
        },
        "ask": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/permissionRule"
          },
          "description": "List of permission rules that should always prompt for confirmation",
          "uniqueItems": true
        },
        "defaultMode": {
          "type": "string",
          "enum": ["acceptEdits", "bypassPermissions", "default", "plan"],
          "description": "Default permission mode when Claude Code needs access"
        },
        "disableBypassPermissionsMode": {
          "type": "string",
          "enum": ["disable"],
          "description": "Disable the ability to bypass permission prompts"
        },
        "additionalDirectories": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          },
          "description": "Additional directories to include in the permission scope",
          "examples": [["//Users/alice/Documents", "~/projects"]],
          "uniqueItems": true
        }
      },
      "additionalProperties": false,
      "description": "Tool usage permissions configuration. See https://code.claude.com/docs/en/iam#configuring-permissions",
      "examples": [
        {
          "allow": ["Bash(git add:*)"],
          "ask": ["Bash(gh pr create:*)", "Bash(git commit:*)"],
          "deny": ["Read(*.env)", "Bash(rm:*)", "Bash(curl:*)"],
          "defaultMode": "default"
        }
      ]
    },
    "language": {
      "type": "string",
      "description": "Preferred language for Claude's responses",
      "examples": ["japanese", "spanish", "french"]
    },
    "model": {
      "type": "string",
      "description": "Override the default model used by Claude Code. See https://code.claude.com/docs/en/model-config"
    },
    "enableAllProjectMcpServers": {
      "type": "boolean",
      "description": "Whether to automatically approve all MCP servers in the project. See https://code.claude.com/docs/en/mcp",
      "examples": [true]
    },
    "enabledMcpjsonServers": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "List of approved MCP servers from .mcp.json. See https://code.claude.com/docs/en/mcp",
      "examples": [["memory", "github"]]
    },
    "disabledMcpjsonServers": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "List of rejected MCP servers from .mcp.json. See https://code.claude.com/docs/en/mcp",
      "examples": [["filesystem"]]
    },
    "allowedMcpServers": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "serverName": {
            "type": "string",
            "pattern": "^[a-zA-Z0-9_-]+$",
            "description": "Name of the MCP server that users are allowed to configure"
          }
        },
        "required": ["serverName"],
        "additionalProperties": false
      },
      "description": "Enterprise allowlist of MCP servers that can be used. Applies to all scopes including enterprise servers from managed-mcp.json. If undefined, all servers are allowed. If empty array, no servers are allowed. Denylist takes precedence - if a server is on both lists, it is denied. See https://code.claude.com/docs/en/mcp#managed-mcp-configuration"
    },
    "deniedMcpServers": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "serverName": {
            "type": "string",
            "pattern": "^[a-zA-Z0-9_-]+$",
            "description": "Name of the MCP server that is explicitly blocked"
          }
        },
        "required": ["serverName"],
        "additionalProperties": false
      },
      "description": "Enterprise denylist of MCP servers that are explicitly blocked. If a server is on the denylist, it will be blocked across all scopes including enterprise. Denylist takes precedence over allowlist - if a server is on both lists, it is denied. See https://code.claude.com/docs/en/mcp#managed-mcp-configuration"
    },
    "hooks": {
      "type": "object",
      "additionalProperties": false,
      "description": "Custom commands to run before/after tool executions. See https://code.claude.com/docs/en/hooks",
      "examples": [
        {
          "PostToolUse": [
            {
              "matcher": "Edit|Write",
              "hooks": [
                {
                  "type": "command",
                  "command": "prettier --write",
                  "timeout": 5
                }
              ]
            }
          ]
        }
      ],
      "properties": {
        "PreToolUse": {
          "type": "array",
          "description": "Hooks that run before tool calls",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "PostToolUse": {
          "type": "array",
          "description": "Hooks that run after tool completion",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "PostToolUseFailure": {
          "type": "array",
          "description": "Hooks that run after a tool fails",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "PermissionRequest": {
          "type": "array",
          "description": "Hooks that run when a permission dialog appears",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "Notification": {
          "type": "array",
          "description": "Hooks that trigger on notifications",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "UserPromptSubmit": {
          "type": "array",
          "description": "Hooks that run when a user submits a prompt",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "Stop": {
          "type": "array",
          "description": "Hooks that run when agents finish responding",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "SubagentStart": {
          "type": "array",
          "description": "Hooks that run when a subagent is spawned",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "SubagentStop": {
          "type": "array",
          "description": "Hooks that run when subagents finish responding",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "PreCompact": {
          "type": "array",
          "description": "Hooks that run before the context is compacted",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "Setup": {
          "type": "array",
          "description": "Hooks that run during repository initialization (--init, --init-only) or maintenance (--maintenance)",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "SessionStart": {
          "type": "array",
          "description": "Hooks that run when a new session starts",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "SessionEnd": {
          "type": "array",
          "description": "Hooks that run when a session ends",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        }
      }
    },
    "disableAllHooks": {
      "type": "boolean",
      "description": "Disable all hooks and statusLine execution"
    },
    "allowManagedHooksOnly": {
      "type": "boolean",
      "description": "(Managed settings only) Prevent loading of user, project, and plugin hooks. Only allows managed hooks and SDK hooks. See https://code.claude.com/docs/en/settings#hook-configuration"
    },
    "statusLine": {
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "const": "command"
        },
        "command": {
          "type": "string"
        },
        "padding": {
          "type": "number"
        }
      },
      "required": ["type", "command"],
      "additionalProperties": false,
      "description": "Custom status line display configuration. See https://code.claude.com/docs/en/statusline",
      "examples": [
        {
          "type": "command",
          "command": "~/.claude/statusline.sh"
        }
      ]
    },
    "fileSuggestion": {
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "const": "command"
        },
        "command": {
          "type": "string",
          "description": "Shell command to execute for file suggestions"
        }
      },
      "required": ["type", "command"],
      "additionalProperties": false,
      "description": "Configure a custom script for @ file autocomplete. See https://code.claude.com/docs/en/settings#file-suggestion-settings",
      "examples": [
        {
          "type": "command",
          "command": "~/.claude/file-suggestion.sh"
        }
      ]
    },
    "enabledPlugins": {
      "type": "object",
      "additionalProperties": {
        "anyOf": [
          {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          {
            "type": "boolean"
          },
          {
            "not": {}
          }
        ]
      },
      "description": "Enabled plugins using plugin-id@marketplace-id format. Example: { \"formatter@anthropic-tools\": true }. See https://code.claude.com/docs/en/plugins"
    },
    "extraKnownMarketplaces": {
      "type": "object",
      "additionalProperties": {
        "type": "object",
        "properties": {
          "source": {
            "anyOf": [
              {
                "type": "object",
                "properties": {
                  "source": {
                    "type": "string",
                    "const": "url"
                  },
                  "url": {
                    "type": "string",
                    "format": "uri",
                    "description": "Direct URL to marketplace.json file"
                  }
                },
                "required": ["source", "url"],
                "additionalProperties": false
              },
              {
                "type": "object",
                "properties": {
                  "source": {
                    "type": "string",
                    "const": "hostPattern"
                  },
                  "hostPattern": {
                    "type": "string",
                    "description": "Git host pattern to trust for repositories in source specifications"
                  }
                },
                "required": ["source", "hostPattern"],
                "additionalProperties": false
              },
              {
                "type": "object",
                "properties": {
                  "source": {
                    "type": "string",
                    "const": "github"
                  },
                  "repo": {
                    "type": "string",
                    "description": "GitHub repository in owner/repo format"
                  },
                  "ref": {
                    "type": "string",
                    "description": "Git branch or tag to use (e.g., \"main\", \"v1.0.0\"). Defaults to repository default branch."
                  },
                  "path": {
                    "type": "string",
                    "description": "Path to marketplace.json within repo (defaults to .claude-plugin/marketplace.json)"
                  }
                },
                "required": ["source", "repo"],
                "additionalProperties": false
              },
              {
                "type": "object",
                "properties": {
                  "source": {
                    "type": "string",
                    "const": "git"
                  },
                  "url": {
                    "type": "string",
                    "pattern": "\\.git$",
                    "description": "Full git repository URL"
                  },
                  "ref": {
                    "type": "string",
                    "description": "Git branch or tag to use (e.g., \"main\", \"v1.0.0\"). Defaults to repository default branch."
                  },
                  "path": {
                    "type": "string",
                    "description": "Path to marketplace.json within repo (defaults to .claude-plugin/marketplace.json)"
                  }
                },
                "required": ["source", "url"],
                "additionalProperties": false
              },
              {
                "type": "object",
                "properties": {
                  "source": {
                    "type": "string",
                    "const": "npm"
                  },
                  "package": {
                    "type": "string",
                    "description": "NPM package containing marketplace.json"
                  }
                },
                "required": ["source", "package"],
                "additionalProperties": false
              },
              {
                "type": "object",
                "properties": {
                  "source": {
                    "type": "string",
                    "const": "file"
                  },
                  "path": {
                    "type": "string",
                    "description": "Local file path to marketplace.json"
                  }
                },
                "required": ["source", "path"],
                "additionalProperties": false
              },
              {
                "type": "object",
                "properties": {
                  "source": {
                    "type": "string",
                    "const": "directory"
                  },
                  "path": {
                    "type": "string",
                    "description": "Local directory containing .claude-plugin/marketplace.json"
                  }
                },
                "required": ["source", "path"],
                "additionalProperties": false
              }
            ],
            "description": "Where to fetch the marketplace from"
          },
          "installLocation": {
            "type": "string",
            "description": "Local cache path where marketplace manifest is stored (auto-generated if not provided)"
          }
        },
        "required": ["source"],
        "additionalProperties": false
      },
      "description": "Additional marketplaces to make available for this repository. Typically used in repository .claude/settings.json to ensure team members have required plugin sources. See https://code.claude.com/docs/en/plugin-marketplaces"
    },
    "strictKnownMarketplaces": {
      "type": "array",
      "description": "(Managed settings only) Allowlist of plugin marketplaces users can add. Undefined = no restrictions, empty array = lockdown. Uses exact matching for source specifications. See https://code.claude.com/docs/en/settings#strictknownmarketplaces",
      "items": {
        "anyOf": [
          {
            "type": "object",
            "properties": {
              "source": {
                "type": "string",
                "const": "hostPattern"
              },
              "hostPattern": {
                "type": "string",
                "description": "Git host pattern to trust for repositories in source specifications"
              }
            },
            "required": ["source", "hostPattern"],
            "additionalProperties": false
          },
          {
            "type": "object",
            "properties": {
              "source": {
                "type": "string",
                "const": "github"
              },
              "repo": {
                "type": "string",
                "description": "GitHub repository in owner/repo format"
              },
              "ref": {
                "type": "string",
                "description": "Git branch, tag, or SHA"
              },
              "path": {
                "type": "string",
                "description": "Subdirectory path"
              }
            },
            "required": ["source", "repo"],
            "additionalProperties": false
          },
          {
            "type": "object",
            "properties": {
              "source": {
                "type": "string",
                "const": "git"
              },
              "url": {
                "type": "string",
                "description": "Full git repository URL"
              },
              "ref": {
                "type": "string",
                "description": "Git branch, tag, or SHA"
              },
              "path": {
                "type": "string",
                "description": "Subdirectory path"
              }
            },
            "required": ["source", "url"],
            "additionalProperties": false
          },
          {
            "type": "object",
            "properties": {
              "source": {
                "type": "string",
                "const": "url"
              },
              "url": {
                "type": "string",
                "format": "uri",
                "description": "Direct URL to marketplace.json"
              },
              "headers": {
                "type": "object",
                "additionalProperties": {
                  "type": "string"
                },
                "description": "HTTP headers for authenticated access"
              }
            },
            "required": ["source", "url"],
            "additionalProperties": false
          },
          {
            "type": "object",
            "properties": {
              "source": {
                "type": "string",
                "const": "npm"
              },
              "package": {
                "type": "string",
                "description": "NPM package name (supports scoped packages)"
              }
            },
            "required": ["source", "package"],
            "additionalProperties": false
          },
          {
            "type": "object",
            "properties": {
              "source": {
                "type": "string",
                "const": "file"
              },
              "path": {
                "type": "string",
                "description": "Absolute path to marketplace.json file"
              }
            },
            "required": ["source", "path"],
            "additionalProperties": false
          },
          {
            "type": "object",
            "properties": {
              "source": {
                "type": "string",
                "const": "directory"
              },
              "path": {
                "type": "string",
                "description": "Absolute path to directory containing .claude-plugin/marketplace.json"
              }
            },
            "required": ["source", "path"],
            "additionalProperties": false
          }
        ]
      },
      "examples": [
        [
          { "source": "github", "repo": "acme-corp/approved-plugins" },
          { "source": "npm", "package": "@acme-corp/compliance-plugins" }
        ]
      ]
    },
    "skippedMarketplaces": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "List of marketplace names the user has chosen not to install when prompted"
    },
    "skippedPlugins": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "List of plugin IDs (plugin@marketplace format) the user has chosen not to install when prompted"
    },
    "forceLoginMethod": {
      "type": "string",
      "enum": ["claudeai", "console"],
      "description": "Force a specific login method: \"claudeai\" for Claude Pro/Max, \"console\" for Console billing",
      "examples": ["claudeai"]
    },
    "forceLoginOrgUUID": {
      "type": "string",
      "description": "Organization UUID to use for OAuth login",
      "examples": ["xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"],
      "minLength": 1
    },
    "otelHeadersHelper": {
      "type": "string",
      "description": "Path to a script that outputs OpenTelemetry headers",
      "minLength": 1
    },
    "outputStyle": {
      "type": "string",
      "description": "Controls the output style for assistant responses. See https://code.claude.com/docs/en/output-styles",
      "examples": ["default", "Explanatory", "Learning"],
      "minLength": 1
    },
    "skipWebFetchPreflight": {
      "type": "boolean",
      "description": "Skip the WebFetch blocklist check for enterprise environments with restrictive security policies"
    },
    "sandbox": {
      "type": "object",
      "description": "Sandbox execution configuration. See https://code.claude.com/docs/en/sandboxing",
      "properties": {
        "network": {
          "type": "object",
          "properties": {
